  const now = getNow()
  const {
    valid,
    message,
    isValidating,
    price,
    maxClaimablePerWallet,
    mintStatus,
  } = useValidate(
    mintProps.address,
    mintProps.mintType,
    mintProps.price,
    mintProps.mintDotFunStatus
  )

  const isMintedOut = mintStatus === MintStatus.MintedOut

  if (
    (mintProps.endDate && now >= mintProps.endDate) ||
    isMintedOut ||
